######################################################################
# Test scripts
######################################################################

# Add your test scripts in TEST_SCRIPTS list. They will be executed
# in given order.
#
# Add test tear down scripts in ENSURE_SCRIPTS list, to be invoked
# after the whole test script procedure. The scripts listed in
# ENSURE_SCRIPTS will be executed even if test procedure forcibly
# quits by user interruption.
#
# Each test script must have executable permission. To find the
# script in the same directory, don't forget to prefix it with "./".
# 
# The test script must return non-zero value if it meets any error.

# 1. Trivial tests for typical Jenkins CI builds
#    (invoked with `mvn test [-Dtest.level={1..5}]`)
TEST_SCRIPTS=("mvn iter:run -Ddaemon=true -Dprog=* -v")
ENSURE_SCRIPTS=("mvn iter:stop -Dprog=* -v -DignoreStopped")

# 2. Additional tests for release and local development builds
#    (invoked with `mvn test [-Dtest.level={2..5}]`)
if [ "${TEST_LEVEL:=2}" -ge 2 ]; then
    TEST_SCRIPTS+=()
    ENSURE_SCRIPTS+=()
fi

# 3. Additional complex tests only executed on full QA/Sonar builds
#    (invoked with `mvn test -Dtest.level={3..5}`)
if [ "${TEST_LEVEL:=2}" -ge 3 ]; then
    TEST_SCRIPTS+=()
    ENSURE_SCRIPTS+=()
fi

######################################################################
# Test execution
######################################################################

source sunit
run_tests

exit $?
